fun main(args: Array<String>) {
    var (a, b, n) = readLine()!!.split(' ').map { it.toInt() }

    fun gcd(x: Int, y: Int) = x.toBigInteger().gcd(y.toBigInteger()).toInt()

    while (true) {
        val ax = gcd(a, n)
        if (ax > n) {
            println(1)
            return
        }
        n -= ax
        val bx = gcd(b, n)
        if (bx > n) {
            println(0)
            return
        }
        n -= bx
    }
}
